import urllib.request, urllib.parse, json
qs=['generative retrieval recommendation semantic IDs','hyperbolic sequential recommendation next item','hyperbolic generative recommendation semantic ID']
for q in qs:
 u='https://api.openalex.org/works?search='+urllib.parse.quote(q)+'&per-page=10'
 try:
  d=json.load(urllib.request.urlopen(u,timeout=20))
  print('\nQUERY',q)
  for x in d['results'][:10]: print(x.get('display_name'), x.get('doi'), x.get('publication_year'), x.get('ids',{}).get('openalex'))
 except Exception as e: print(e)
PY

