import urllib.request,urllib.parse,json
for q in ['Recommender Systems with Generative Retrieval','Hyperbolic Hypergraphs for Sequential Recommendation','Self-Attentive Sequential Recommendations with Hyperbolic Representations','Hyperbolic Translation-Based Sequential Recommendation']:
 u='https://api.openalex.org/works?search='+urllib.parse.quote(q)+'&per-page=3'
